-- Installed TW MasterData SHA-256: 730d2aea3e7138d0212b64d80d7fe13e2c72ff03086944f3c8d2e325b4b592cc

ALTER TABLE public.player_climbing_state
    ADD COLUMN climbing_code BIGINT,
    ADD COLUMN week_number BIGINT,
    ADD COLUMN checked_at BIGINT NOT NULL DEFAULT 0,
    ADD COLUMN run_state JSONB NOT NULL DEFAULT '{}'::jsonb;
CREATE TABLE public.player_climbing_battles (
    player_id TEXT NOT NULL REFERENCES public.players(player_id) ON DELETE CASCADE,
    unique_id BYTEA NOT NULL CHECK (octet_length(unique_id)=16),
    round_index INTEGER NOT NULL CHECK (round_index BETWEEN 0 AND 1),
    week_number BIGINT NOT NULL,
    climbing_code BIGINT NOT NULL,
    floor_number INTEGER NOT NULL CHECK (floor_number BETWEEN 1 AND 5),
    start_hash TEXT NOT NULL,
    party BYTEA NOT NULL,
    state TEXT NOT NULL CHECK (state IN ('active','settled','abandoned')),
    result_hash TEXT,
    response BYTEA,
    PRIMARY KEY (player_id,unique_id,round_index)
);
CREATE UNIQUE INDEX player_climbing_active_battle ON public.player_climbing_battles(player_id)
    WHERE state='active';
CREATE TABLE public.player_climbing_rewards (
    player_id TEXT NOT NULL REFERENCES public.players(player_id) ON DELETE CASCADE,
    week_number BIGINT NOT NULL,
    floor_number INTEGER NOT NULL CHECK (floor_number BETWEEN 1 AND 5),
    received_at BIGINT NOT NULL,
    PRIMARY KEY (player_id,week_number,floor_number)
);
